import * as React from "react";

export type CoinIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function CoinIcon({ size = 20, ...props }: CoinIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <circle cx={12} cy={12} r={8} />
      <circle cx={12} cy={12} r={4.5} />
    </svg>
  );
}
